css:
.taxplan-sim-container {
    padding: 28px;
    background: #f0f2f5;
    min-height: 100vh;
    font-family: -apple-system, 'Segoe UI', 'Inter', Helvetica, Arial, sans-serif;
    color: #1a2744;
}

.taxplan-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #2a3f66 100%);
    color: #ffffff;
    padding: 32px 36px;
    margin-bottom: 24px;
    border-radius: 4px;
    position: relative;
    overflow: hidden;
}
.taxplan-sim-header::after {
    content: '';
    position: absolute;
    top: 0;
    right: 0;
    width: 200px;
    height: 100%;
    background: linear-gradient(135deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.04) 100%);
}
.taxplan-sim-header-badge {
    display: inline-block;
    background: rgba(255,255,255,0.15);
    border: 1px solid rgba(255,255,255,0.25);
    color: #ffffff;
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.15em;
    padding: 4px 12px;
    border-radius: 2px;
    margin-bottom: 12px;
    text-transform: uppercase;
}
.taxplan-sim-container h1 {
    font-size: 1.6rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    letter-spacing: -0.01em;
}
.taxplan-sim-subtitle {
    font-size: 0.85rem;
    opacity: 0.75;
    margin: 0;
    font-weight: 400;
}

.taxplan-sim-period-counter {
    text-align: center;
    font-size: 0.85rem;
    color: #5a6a85;
    margin-bottom: 24px;
    font-weight: 500;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}
.taxplan-sim-period-counter span {
    margin: 0 3px;
}

.taxplan-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 20px;
}
.taxplan-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #e2e6ec;
    border-radius: 4px;
    padding: 20px 16px;
    text-align: center;
    transition: box-shadow 0.2s ease;
    position: relative;
}
.taxplan-sim-kpi-card:hover {
    box-shadow: 0 4px 16px rgba(26,39,68,0.08);
}
.taxplan-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: #1a2744;
}
.taxplan-sim-kpi-danger::before {
    background: #dc2626;
}
.taxplan-sim-kpi-success::before {
    background: #16a34a;
}
.taxplan-sim-kpi-warning::before {
    background: #d97706;
}
.taxplan-sim-kpi-icon {
    font-size: 1.3rem;
    margin-bottom: 6px;
}
.taxplan-sim-kpi-label {
    font-size: 0.68rem;
    color: #5a6a85;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 600;
    margin-bottom: 8px;
}
.taxplan-sim-kpi-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.2;
}
.taxplan-sim-kpi-danger .taxplan-sim-kpi-value {
    color: #dc2626;
}
.taxplan-sim-kpi-success .taxplan-sim-kpi-value {
    color: #16a34a;
}
.taxplan-sim-kpi-warning .taxplan-sim-kpi-value {
    color: #d97706;
}

.taxplan-sim-info-bar {
    display: flex;
    gap: 24px;
    background: #ffffff;
    border: 1px solid #e2e6ec;
    border-radius: 4px;
    padding: 12px 20px;
    margin-bottom: 24px;
}
.taxplan-sim-info-item {
    display: flex;
    align-items: center;
    gap: 8px;
}
.taxplan-sim-info-label {
    font-size: 0.75rem;
    color: #5a6a85;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 600;
}
.taxplan-sim-info-value {
    font-size: 0.95rem;
    font-weight: 700;
    color: #1a2744;
}

.taxplan-sim-briefing {
    background: #ffffff;
    border: 1px solid #e2e6ec;
    border-left: 4px solid #2563eb;
    border-radius: 4px;
    margin-bottom: 24px;
    overflow: hidden;
}
.taxplan-sim-briefing-header {
    background: #f7f8fb;
    padding: 16px 24px;
    border-bottom: 1px solid #e2e6ec;
}
.taxplan-sim-briefing-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #2563eb;
}
.taxplan-sim-briefing-body {
    padding: 20px 24px;
    font-size: 0.88rem;
    line-height: 1.65;
    color: #374151;
}

.taxplan-sim-controls {
    background: #ffffff;
    border: 1px solid #e2e6ec;
    border-radius: 4px;
    padding: 24px;
    margin-bottom: 24px;
}
.taxplan-sim-controls h3 {
    margin: 0 0 20px 0;
    font-size: 0.95rem;
    font-weight: 700;
    color: #1a2744;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.taxplan-sim-input-row {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
    margin-bottom: 24px;
}
.taxplan-sim-input-group {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.taxplan-sim-input-group label {
    font-size: 0.75rem;
    font-weight: 600;
    color: #5a6a85;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.taxplan-sim-container input[type="number"],
.taxplan-sim-container select {
    background: #f7f8fb;
    border: 1px solid #d1d5db;
    color: #1a2744;
    border-radius: 4px;
    padding: 10px 14px;
    font-size: 0.95rem;
    font-weight: 600;
    width: 100%;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    font-family: inherit;
}
.taxplan-sim-container input[type="number"]:focus,
.taxplan-sim-container select:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37,99,235,0.12);
    background: #ffffff;
}
.taxplan-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
}
.taxplan-sim-btn-submit {
    background: #2563eb;
    border: none;
    color: #ffffff;
    padding: 12px 32px;
    font-size: 0.9rem;
    font-weight: 600;
    border-radius: 4px;
    cursor: pointer;
    transition: background 0.2s ease;
    letter-spacing: 0.02em;
}
.taxplan-sim-btn-submit:hover {
    background: #1d4ed8;
}
.taxplan-sim-btn-undo {
    background: transparent;
    border: 1px solid #d1d5db;
    color: #5a6a85;
    padding: 8px 18px;
    font-size: 0.8rem;
    border-radius: 4px;
    cursor: pointer;
    transition: border-color 0.2s ease;
}
.taxplan-sim-btn-undo:hover {
    border-color: #9ca3af;
    color: #374151;
}

.taxplan-sim-history {
    background: #ffffff;
    border: 1px solid #e2e6ec;
    border-radius: 4px;
    margin-bottom: 24px;
    overflow: hidden;
}
.taxplan-sim-container .table {
    margin: 0;
    font-size: 0.85rem;
}
.taxplan-sim-container .table thead th {
    background: #f7f8fb;
    color: #5a6a85;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.72rem;
    border-bottom: 2px solid #e2e6ec;
    padding: 12px 16px;
}
.taxplan-sim-container .table td {
    padding: 10px 16px;
    color: #374151;
    font-weight: 500;
    vertical-align: middle;
}

.taxplan-sim-chart {
    background: #ffffff;
    border: 1px solid #e2e6ec;
    border-radius: 4px;
    padding: 24px;
    min-height: 280px;
}
.taxplan-sim-chart canvas {
    max-height: 260px;
}

@media (max-width: 768px) {
    .taxplan-sim-container {
        padding: 16px;
    }
    .taxplan-sim-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
    }
    .taxplan-sim-input-row {
        grid-template-columns: 1fr;
    }
    .taxplan-sim-info-bar {
        flex-direction: column;
        gap: 8px;
    }
    .taxplan-sim-header {
        padding: 24px 20px;
    }
    .taxplan-sim-container h1 {
        font-size: 1.3rem;
    }
}

