            } else if (roundIdx === 1) {
                var priceDiff = Math.abs(d.primaryValue - 47.5);
                var priceScore = Math.max(0, 40 - priceDiff * 10);
                var docInvestment = Math.min(30, (d.secondaryValue / 500) * 30);
                var stanceScores = { cooperative: 30, assertive: 20, aggressive: 5 };
                var stanceScore = stanceScores[d.strategyChoice] || 10;
                roundScore = Math.round(priceScore + docInvestment + stanceScore);
                roundCost = d.secondaryValue * 1000;
                complianceGain = Math.round(roundScore * 0.2);
                exposureReduction = roundScore > 70 ? 1500000 : (roundScore > 40 ? 750000 : 250000);
                ds.transferPrice = d.primaryValue;
            } else if (roundIdx === 2) {
                var settleDiff = Math.abs(d.primaryValue - 7.5);
                var settleScore = Math.max(0, 40 - settleDiff * 8);
                var legalScore = Math.min(30, (d.secondaryValue / 800) * 30);
                var coopScores = { full: 30, partial: 15, minimal: 5 };
                var coopScore = coopScores[d.strategyChoice] || 5;
                roundScore = Math.round(settleScore + legalScore + coopScore);
                roundCost = (d.primaryValue * 1000000) + (d.secondaryValue * 1000);
                complianceGain = Math.round(roundScore * 0.15);
                criminalReduction = d.strategyChoice === 'full' ? 50 : (d.strategyChoice === 'partial' ? 25 : 5);
                exposureReduction = roundScore > 70 ? 3000000 : (roundScore > 40 ? 1500000 : 500000);
            } else {
                var newPriceDiff = Math.abs(d.primaryValue - 48);
                var newPriceScore = Math.max(0, 40 - newPriceDiff * 8);
                var budgetScore = Math.min(30, (d.secondaryValue / 600) * 30);
                var govScores = { comprehensive: 30, standard: 20, basic: 10 };
                var govScore = govScores[d.strategyChoice] || 10;
                roundScore = Math.round(newPriceScore + budgetScore + govScore);
                roundCost = d.secondaryValue * 1000;
                complianceGain = Math.round(roundScore * 0.35);
                ds.transferPrice = d.primaryValue;
                criminalReduction = 10;
            }

            roundScore = Math.min(100, Math.max(0, roundScore));

            // Idempotency guard: a duplicate/preview call for an already-scored round must not
            // double-mutate live domainState. Normal play (one call/round) is unaffected --
            // at round N (roundIdx N-1) scoreHistory holds exactly N-1 entries.
            if (ds.scoreHistory && ds.scoreHistory.length > roundIdx) {
                ds = JSON.parse(JSON.stringify(ds));
            }

            ds.cash -= roundCost;
            ds.totalCost += roundCost;
            ds.complianceScore = Math.min(100, ds.complianceScore + complianceGain);
            ds.taxExposure = Math.max(0, ds.taxExposure - exposureReduction);
            ds.criminalRisk = Math.max(0, ds.criminalRisk - criminalReduction);
            ds.scoreHistory.push(roundScore);
            ds.costHistory.push(ds.totalCost);
            ds.complianceHistory.push(ds.complianceScore);

            // Platform score: mean of the round scores so far, the same avgScore out of 100 that getPerformanceSummary reports at the end
            var scoredSoFar = ds.scoreHistory.slice(0, roundIdx + 1);
            var scoredSum = 0;
            for (var si = 0; si < scoredSoFar.length; si++) scoredSum += (Number(scoredSoFar[si]) || 0);
            var platformScore = scoredSoFar.length ? Math.round(scoredSum / scoredSoFar.length) : 0;
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, platformScore)) });

            var self = this;
            var maxP = parseInt(state.maxPeriods, 10) || 4;
            if ((state.currentPeriod || 1) < maxP) {
                setTimeout(((__eqilNext) => function() {
                    try {
                        // Read live post-increment state so the panel matches the actual next
                        // round (previously a stale +1 advanced two rounds -> R2 skipped).
                        var live = (window.mySimulation && window.mySimulation.state)
                            ? window.mySimulation.state
                            : { currentPeriod: __eqilNext };
                        self._updateBriefing(live);
                    } catch (e) {}
                })((state.currentPeriod || 1) + 1), 500);
            }

            return {
                period: state.currentPeriod,
                roundScore: roundScore,
                roundCost: roundCost,
                cash: ds.cash,
                taxExposure: ds.taxExposure,
                complianceScore: ds.complianceScore,
                criminalRisk: ds.criminalRisk,
                transferPrice: ds.transferPrice
            };
        }

