        getPerformanceSummary(history) {
            var t = function(k){ try { return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k; } catch(e){ return k; } };
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.roundScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var avgScore = Math.round(totalScore / scores.length);
            var lastEntry = history[history.length - 1];
            var finalCompliance = lastEntry.domainState ? lastEntry.domainState.complianceScore : 0;
            var finalExposure = lastEntry.domainState ? lastEntry.domainState.taxExposure : 0;
            var finalCost = lastEntry.domainState ? lastEntry.domainState.totalCost : 0;
            var finalCriminal = lastEntry.domainState ? lastEntry.domainState.criminalRisk : 0;

            var performance = t('perf_needs');
            if (avgScore >= 75 && finalCompliance >= 70) performance = t('perf_excellent');
            else if (avgScore >= 55 && finalCompliance >= 50) performance = t('perf_good');
            else if (avgScore >= 35) performance = t('perf_adequate');

            var insights = [];
            if (finalCompliance >= 80) {
                insights.push(t('ins_comp_high'));
            } else {
                insights.push(t('ins_comp_low'));
            }
            if (finalExposure <= 1000000) {
                insights.push(t('ins_exp_low'));
            } else {
                insights.push(t('ins_exp_high'));
            }
            if (finalCriminal <= 20) {
                insights.push(t('ins_crim_low'));
            } else {
                insights.push(t('ins_crim_high'));
            }

            return {
                totalScore: totalScore,
                avgScore: avgScore,
                finalCompliance: finalCompliance,
                totalCost: finalCost,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.roundScore < 30) return window.mySimulation.t('hint_low_score');
            if (results.roundScore >= 80) return window.mySimulation.t('hint_high_score');
            if (state.domainState.criminalRisk > 60 && state.currentPeriod >= 3) return window.mySimulation.t('hint_criminal');
            return null;
        }

