        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl && window.mySimulation) {
                titleEl.innerHTML = window.mySimulation.t(round.titleKey);
            }

            var briefEl = document.getElementById('briefingText');
            if (briefEl && window.mySimulation) {
                briefEl.innerHTML = window.mySimulation.t(round.briefingKey);
            }

            var primaryInput = document.getElementById('primaryInput');
            if (primaryInput) {
                primaryInput.min = round.primaryMin;
                primaryInput.max = round.primaryMax;
                primaryInput.step = round.primaryStep;
                // Answer input: starts blank every round (the R4 default 48 was the scored target)
                primaryInput.value = '';
            }

            var primaryLabel = document.getElementById('primaryLabel');
            if (primaryLabel && window.mySimulation) {
                primaryLabel.textContent = window.mySimulation.t(round.primaryLabelKey);
            }

            var secondaryInput = document.getElementById('secondaryInput');
            if (secondaryInput) {
                secondaryInput.min = round.secondaryMin;
                secondaryInput.max = round.secondaryMax;
                secondaryInput.step = round.secondaryStep;
                secondaryInput.value = round.secondaryDefault;
            }

            var secondaryLabel = document.getElementById('secondaryLabel');
            if (secondaryLabel && window.mySimulation) {
                secondaryLabel.textContent = window.mySimulation.t(round.secondaryLabelKey);
            }

            var strategySelect = document.getElementById('strategySelect');
            if (strategySelect && window.mySimulation) {
                strategySelect.innerHTML = '';
                round.selectOptions.forEach(function(opt) {
                    var option = document.createElement('option');
                    option.value = opt.value;
                    option.textContent = window.mySimulation.t(opt.textKey);
                    strategySelect.appendChild(option);
                });
            }

            var strategyLabel = document.getElementById('strategyLabel');
            if (strategyLabel && window.mySimulation) {
                strategyLabel.textContent = window.mySimulation.t(round.selectLabelKey);
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new TaxPlanningAdapter(), {
            simulationType: 'tax_planning_487',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
